<section class="content-section"><div class="container-xl"><div class="section-heading-row"><div><span class="section-kicker">FAQ</span><h2><?php echo esc_html(estatein_field('faq_heading',false,'Frequently Asked Questions')); ?></h2><p><?php echo esc_html(estatein_field('faq_description',false,'Find answers to common questions about Estatein services, property listings, and the real estate process.')); ?></p></div><?php echo estatein_button(estatein_field('faq_button_label',false,'View All FAQs'),estatein_field('faq_button_url',false,estatein_archive_url('faq')),'btn btn-outline-light'); ?></div><div class="row g-4 mt-2"><?php $q=new WP_Query(['post_type'=>'faq','posts_per_page'=>(int)estatein_field('faq_count',false,3)]);if($q->have_posts()):while($q->have_posts()):$q->the_post(); ?><div class="col-lg-4"><article class="faq-card h-100"><h3><?php the_title(); ?></h3><p><?php echo esc_html(estatein_field('faq_short_answer',get_the_ID(),wp_trim_words(get_the_content(),25))); ?></p><a href="<?php the_permalink(); ?>">Read More ↗</a></article></div><?php endwhile;wp_reset_postdata();else: ?><div class="col-12"><div class="empty-state">Add FAQ posts to populate this section.</div></div><?php endif; ?></div></div></section>
